@mark.asyncio
async def test_zero_x_swapper_build_transactions_data_with_approval(
    zero_x_api_client: ZeroXApiClient,
    zero_x_swapper: ZeroXSwapper,
    chain: Chain,
    investment_parameters: InvestmentParameters,
):
    chain.is_native_token.return_value = False
    zero_x_api_client.get_price.return_value = Price(
        issues=Issues(
            allowance=Allowance(spender="0x2170ed0880ac9a755fd29b2688956bd959f933f8")
        ),
        sellAmount="254516995428172740",
        buyAmount="1000000000000000000",
        buyToken=bnb_token.address,
        sellToken=eth_token.address,
        fees=Fees(),
    )

    zero_x_api_client.get_quote.return_value = QuoteResult(
        root=Quote(
            liquidityAvailable=True,
            permit2=None,
            transaction=Transaction(
                to="0x779a74436eda060911b2c4f209d34ea155f3df09",
                data="",
                gas="322930",
                gasPrice="100000000",
                value="1000000000000000000",
            ),
            sellAmount="254516995428172740",
            sellToken=eth_token.address,
            buyAmount="1000000000000000000",
            buyToken=bnb_token.address,
            fees=Fees(
                integratorFee=None,
                zeroExFee=Fee(
                    amount="382349016667264",
                    token="0x2170ed0880ac9a755fd29b2688956bd959f933f8",
                    type="volume",
                ),
                gasFee=None,
            ),
        )
    )

    transactions_data = await zero_x_swapper.build_transactions(
        order=Order(
            id="2",
            buy_balance=Balance(asset=bnb_token, amount=Decimal(1)),
            sell_balance=Balance(asset=eth_token, amount=Decimal(0.2)),
            type="SELL",
            tries=[],
            created_at=1234567890,
            status="PENDING",
            trigger="MANUAL",
            basket_id=None,
        ),
        investment_parameters=investment_parameters,
    )

    assert len(transactions_data) == 2

    assert transactions_data[0].type == "SIGN"
    assert transactions_data[0].amount == 0
    assert transactions_data[0].to_address == eth_token.address
    assert transactions_data[0].encoded_input is not None

    assert transactions_data[1].type == "SEND"


@mark.asyncio
async def test_zero_x_swapper_get_wallet_in_token(
    zero_x_api_client: ZeroXApiClient,
    chain: Chain,
    contract: Contract,
    configuration: Configuration,
    w3: AsyncWeb3,
    investment_parameters: InvestmentParameters,
):
    token = usdt_token

    tokens_balance = [
        Balance(asset=sol_token, amount=Decimal("1.0")),
        Balance(asset=eth_token, amount=Decimal("4.0")),
        Balance(asset=bnb_token, amount=Decimal("10.0")),
    ]

    zero_x_api_client.get_price.side_effect = [
        Price(
            issues=Issues(),
            buyAmount="300000000000000000000",
            sellAmount="1000000000000000000",
            buyToken=usdt_token.address,
            sellToken=sol_token.address,
            fees=Fees(),
        ),
        Price(
            issues=Issues(),
            buyAmount="1100000000000000000000",
            sellAmount="4000000000000000000",
            buyToken=usdt_token.address,
            sellToken=eth_token.address,
            fees=Fees(),
        ),
        Price(
            issues=Issues(),
            buyAmount="10000000000000000000",
            sellAmount="10000000000000000000",
            buyToken=usdt_token.address,
            sellToken=bnb_token.address,
            fees=Fees(),
        ),
    ]

    zero_x_swapper = ZeroXSwapper(
        api_client=zero_x_api_client,
        chain=chain,
        contract=contract,
        configuration=configuration,
        w3=w3,
    )

    wallet = await zero_x_swapper.get_wallet_in_token(
        tokens_balance, token, investment_parameters
    )

    assert wallet == Wallet(
        balances=[
            ConvertedBalance(
                sell_balance=Balance(asset=sol_token, amount=Decimal("1.0")),
                buy_balance=Balance(asset=usdt_token, amount=Decimal("300")),
            ),
            ConvertedBalance(
                sell_balance=Balance(asset=eth_token, amount=Decimal("4.0")),
                buy_balance=Balance(asset=usdt_token, amount=Decimal("1100.0")),
            ),
            ConvertedBalance(
                sell_balance=Balance(asset=bnb_token, amount=Decimal("10.0")),
                buy_balance=Balance(asset=usdt_token, amount=Decimal("10.0")),
            ),
        ],
        total_balance=Balance(asset=usdt_token, amount=Decimal("1410.0")),
    )


@mark.asyncio
async def test_zero_x_swapper_get_wallet_in_token_same_token(
    zero_x_api_client: ZeroXApiClient,
    chain: Chain,
    contract: Contract,
    configuration: Configuration,
    w3: AsyncWeb3,
    investment_parameters: InvestmentParameters,
):
    token = usdt_token

    tokens_balance = [
        Balance(asset=usdt_token, amount=Decimal("10.0")),
    ]

    zero_x_swapper = ZeroXSwapper(
        api_client=zero_x_api_client,
        chain=chain,
        contract=contract,
        configuration=configuration,
        w3=w3,
    )

    wallet = await zero_x_swapper.get_wallet_in_token(
        tokens_balance, token, investment_parameters
    )

    zero_x_swapper.api_client.get_price.assert_not_called()

    assert wallet == Wallet(
        balances=[
            ConvertedBalance(
                sell_balance=Balance(asset=usdt_token, amount=Decimal("10.0")),
                buy_balance=Balance(asset=usdt_token, amount=Decimal("10.0")),
            ),
        ],
        total_balance=Balance(asset=usdt_token, amount=Decimal("10.0")),
    )
